def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

sorted_list = [1, 3, 5, 7, 9, 11]
print(binary_search(sorted_list, 7))

test_arr = [65, 73, 32, 114, 105, 103, 104, 116, 115]
test_arr.sort()
print(binary_search(test_arr, 73))

